/* [FW-DEMO] heat-episode replay input. See hg_fw_demo.h. SIMULATED INPUT ONLY: no threshold, rule or decision here. */
#include "fw_flags.h"
#include "hg_fw_demo.h"
#include <math.h>
#include <string.h>

#include "hg_demo_trace.h"   /* GENERATED by fw/tools/make_demo_trace.py (velders) */

const hg_demo_row_t *const hg_demo_trace = HG_DEMO_TRACE;
const uint16_t hg_demo_n = HG_DEMO_N;
const uint16_t hg_demo_pre = HG_DEMO_PRE;
int32_t hg_demo_first(void) { return -(int32_t)(HG_DEMO_WARM + HG_DEMO_PRE); }
const uint16_t hg_demo_start_mod = HG_DEMO_START_MOD;

static int32_t amod(int32_t k) { return (int32_t)HG_DEMO_START_MOD + k; }
uint16_t hg_demo_mod(int32_t k) { int32_t a = amod(k); return (uint16_t)(((a % 1440) + 1440) % 1440); }
int32_t hg_demo_day(int32_t k) { int32_t a = amod(k); return HG_DEMO_DAY0 + (a >= 0 ? a / 1440 : -((1439 - a) / 1440)); }
uint32_t hg_demo_ms(int32_t k) { return (uint32_t)(k - hg_demo_first()) * 60000u; }

const hg_demo_row_t *hg_demo_row(int32_t k)
{
  if (k < -HG_DEMO_PRE) k = -HG_DEMO_PRE;
  if (k >= HG_DEMO_N) k = HG_DEMO_N - 1;
  return &HG_DEMO_TRACE[k + HG_DEMO_PRE];
}

static uint32_t lcg(uint32_t *r) { *r = *r * 1664525u + 1013904223u; return (*r >> 8) & 0xFFFFFFu; }
/* linear between this minute's row and the next, in integers (exact; the only float op is one division) */
static float lerp100(int16_t a, int16_t b, uint8_t sec) { return (float)((int32_t)a * (60 - sec) + (int32_t)b * sec) / 6000.0f; }

void hg_demo_sec(int32_t k, uint8_t sec, uint8_t ppg_on, uint32_t *rng, hg_fw_sec_t *q)
{
  memset(q, 0, sizeof *q);
  if (k < -HG_DEMO_PRE) {                          /* calm warm-up: test_alerts.c's recipe (25 C room, rest pulse, day/night) */
    const uint16_t mod = hg_demo_mod(k); const int night = mod < 7 * 60 || mod >= 23 * 60;
    int32_t nz = (int32_t)(lcg(rng) % 21u) - 10;
    q->t1_c = 33.8f; q->t2_c = 32.2f; q->tair_c = 25.0f; q->rh_pct = 45.0f; q->ppg_on = ppg_on; q->hr_q = 4;
    q->hr_bpm = (float)((night ? 580 : 680) + nz) / 10.0f; q->pi_pct = 0.5f; q->ppg_dc = 110000u;
    const float sd = night ? 0.001f : 0.03f;
    q->a_mean = 1.0f; q->a_n = 25; q->a_m2 = sd * sd * 25.0f; q->a_peak_g = 1.0f + 2.0f * sd; q->zangle_deg = 10.0f;
    return;
  }
  const hg_demo_row_t *r = hg_demo_row(k), *n = (k + 1 < HG_DEMO_N) ? hg_demo_row(k + 1) : r;
  q->t1_c = lerp100(r->t1, n->t1, sec);
  q->t2_c = lerp100(r->t2, n->t2, sec);
  q->tair_c = lerp100(r->ta, n->ta, sec);
  q->rh_pct = (float)((int32_t)r->rh * (60 - sec) + (int32_t)n->rh * sec) / 600.0f;
  q->ppg_on = ppg_on;
  q->hr_q = r->q;
  /* pulse: the minute's reading +-1 bpm per second (integer noise, 0.1 bpm steps) */
  int32_t nz = (int32_t)(lcg(rng) % 21u) - 10;
  q->hr_bpm = r->hr == HG_DEMO_NOHR ? NAN : (float)((int32_t)r->hr + nz) / 10.0f;
  q->pi_pct = (float)r->pi / 1000.0f;
  q->ppg_dc = r->q == 0 ? 5000u : 110000u;
  /* IMU: 25 samples of |a| with the minute's std around 1 g (the per-second M2 that gives exactly that std) */
  float sd = (float)r->astd / 100000.0f;
  q->a_mean = 1.0f; q->a_n = 25; q->a_m2 = sd * sd * 25.0f;
  q->a_peak_g = 1.0f + 2.0f * sd;
  q->zangle_deg = (float)r->z / 100.0f;
}

void hg_demo_ctx(int32_t k, hg_fw_ctx_t *c)
{
  memset(c, 0, sizeof *c);
  c->minute_of_day = hg_demo_mod(k); c->local_day = hg_demo_day(k);
  c->charging = 0; c->vbat = 3.9f; c->ble_bucket = 2; c->forecast72 = NULL; c->has_forecast = 0;
}

void hg_demo_init(hg_demo_st_t *s)
{
  hg2_profile_t p = { 75.0f, 0.0f, 26.0f, 0 };     /* the simulated person = the default wearer (README) */
  hg_twin_defaults(s->tw); hg_twin_acc_init(s->acc); hg_guardian_init(s->g, &p, s->tw); hg_fw_init(s->fw);
  hg_al_init(s->al); hg_plan_init(s->pl); s->rng = HG_DEMO_SEED;
}

void hg_demo_feed_minute(hg_demo_st_t *s, int32_t k)
{
  for (uint8_t sec = 0; sec < 60; sec++) {
    hg_fw_sec_t q; hg_demo_sec(k, sec, (uint8_t)hg_fw_ppg_on(s->fw, sec), &s->rng, &q);
    hg_fw_second(s->fw, &q);
  }
}

void hg_demo_plan_in(const hg_demo_st_t *s, int32_t k, hg_plan_in_t *in)
{
  const hg_fw_t *f = s->fw; const hg_guardian_t *g = s->g;
  memset(in, 0, sizeof *in);
  in->mod = hg_demo_mod(k); in->day = hg_demo_day(k);
  in->warning = (f->minutes && f->last_out.state != HG_ST_OK) || g->help || f->button == 2;
  in->fc72 = NULL; in->have_safe = 0; in->safe_bitmap = 0; in->seed = NULL;
  in->room_c = f->minutes ? f->last_in.s.t_air_c : NAN;
  in->l_valid = g->rt.sleep_valid; in->l_days = g->rt.days_learned; in->l_sleep_on = g->rt.sleep_on; in->l_sleep_off = g->rt.sleep_off;
  in->press = 0;
  in->ext_nudge = (uint8_t)(f->minutes && f->last_out.nudge);
  in->dp_today = NULL; in->dp_tomorrow = NULL;
  in->home_out = f->minutes ? f->last_out.home_out : 0xFF;
  in->herday_only = 1;                              /* 0.9.17: as the band's planIn() (Her Day timing advice only) */
}

void hg_demo_quiet_minute(hg_demo_st_t *s, int32_t k)
{
  hg_demo_feed_minute(s, k);
  hg_fw_ctx_t c; hg_demo_ctx(k, &c); hg_fw_act_t act;
  const uint32_t tms = hg_demo_ms(k);
  hg_fw_minute(s->fw, s->g, s->tw, s->acc, &c, tms, &act);
  hg_al_in_t ai = { &s->fw->last_in, &s->fw->last_out, s->tw->rest_hr, NULL, c.minute_of_day, c.local_day, c.vbat, tms };
  hg_al_out_t ao; hg_al_minute(s->al, &ai, &ao);
  hg_plan_in_t pin; hg_demo_plan_in(s, k, &pin);
  hg_plan_out_t po; hg_al_plan_minute(s->al, &ao, s->pl, &pin, &po);
  if (po.missed) hg_al_event(s->al, HG_EV_NUDGE_MISSED, po.missed, tms);
  if (po.show) hg_al_event(s->al, HG_EV_NUDGE_SHOWN, po.show, tms);
}

void hg_demo_mark_x(uint8_t type, uint8_t x[8])
{
  if (type >= HG_EV_LD_REMIND && type <= HG_EV_LD_NOTE) x[7] = HG_DEMO_X7_SIM;
}
